import{c as s,Q as n,j as p,m as e}from"./chunks/framework.DOi4mjdC.js";const l="/assets/Matmul%E4%BD%BF%E8%83%BDAtomicAdd%E9%80%89%E9%A1%B9%E5%89%8D%E5%90%8E%E6%80%A7%E8%83%BD%E5%AF%B9%E6%AF%94.BbW2QrLF.png",T=JSON.parse('{"title":"Matmul使能AtomicAdd选项","description":"","frontmatter":{},"headers":[{"level":1,"title":"Matmul使能AtomicAdd选项","slug":"matmul使能atomicadd选项"}],"relativePath":"guide/算子实践参考/SIMD算子性能优化/矩阵计算/Matmul使能AtomicAdd选项.md","filePath":"guide/算子实践参考/SIMD算子性能优化/矩阵计算/Matmul使能AtomicAdd选项.md"}'),t={name:"guide/算子实践参考/SIMD算子性能优化/矩阵计算/Matmul使能AtomicAdd选项.md"};function i(c,a,m,o,d,_){return n(),p("div",null,[...a[0]||(a[0]=[e(`<h1 id="matmul使能atomicadd选项" tabindex="-1">Matmul使能AtomicAdd选项 <a class="header-anchor" href="#matmul使能atomicadd选项" aria-label="Permalink to &quot;Matmul使能AtomicAdd选项&quot;">​</a></h1><p>【优先级】中</p><p>【描述】__对于Matmul得到的结果矩阵C(m, n)，若后续需要和GM上的矩阵D(m, n)进行Add操作，则可以在GetTensorC接口或者IterateAll接口的GM通路上，将enAtomic参数设为1，开启AtomicAdd累加操作，在搬出矩阵C到GM时，矩阵C的结果将直接累加到矩阵D的GM地址上，从而实现与矩阵D的Add操作。</p><p>【反例】</p><p>将Matmul的结果矩阵C和GM上的矩阵D分别搬到UB上，做完Add操作后，结果再搬出到GM。这样至少要多分配一块UB内存给矩阵D，假设在分离架构的处理器上执行，将多做三次搬运操作（矩阵C从GM搬到UB、矩阵D从GM搬到UB、Add结果从UB搬出到GM）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> template &lt;class A_TYPE, class B_TYPE, class C_TYPE, class BIAS_TYPE&gt;</span></span>
<span class="line"><span> __aicore__ inline void MatMulKernel(...)</span></span>
<span class="line"><span> {</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    AscendC::Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, CFG_MDL&gt; mm;</span></span>
<span class="line"><span>    TPipe pipe;</span></span>
<span class="line"><span>    REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    mm.SetTensorA(gm_a);</span></span>
<span class="line"><span>    mm.SetTensorB(gm_b);</span></span>
<span class="line"><span>    mm.SetBias(gm_bias);</span></span>
<span class="line"><span>    mm.IterateAll(gm_c);</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    DataCopy(local_c, gm_c, c_size);</span></span>
<span class="line"><span>    DataCopy(local_d, gm_d, d_size);</span></span>
<span class="line"><span>    event_t eventIdMTE2ToV = static_cast&lt;event_t&gt;(GetTPipePtr()-&gt;FetchEventID(HardEvent::MTE2_V));</span></span>
<span class="line"><span>    SetFlag&lt;HardEvent::MTE2_V&gt;(eventIdMTE2ToV);</span></span>
<span class="line"><span>    WaitFlag&lt;HardEvent::MTE2_V&gt;(eventIdMTE2ToV);</span></span>
<span class="line"><span>    Add(local_d, local_d, local_c, d_size);</span></span>
<span class="line"><span>    DataCopy(gm_d, local_d, d_size);</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span> }</span></span>
<span class="line"><span></span></span>
<span class="line"><span> extern &quot;C&quot; __global__ __aicore__ void example_kernel(...)</span></span>
<span class="line"><span> {</span></span>
<span class="line"><span>     ...</span></span>
<span class="line"><span>     typedef AscendC::MatmulType&lt;TPosition::GM, CubeFormat::ND, half&gt; aType; </span></span>
<span class="line"><span>     typedef AscendC::MatmulType&lt;TPosition::GM, CubeFormat::ND, half&gt; bType; </span></span>
<span class="line"><span>     typedef AscendC::MatmulType&lt;TPosition::GM, CubeFormat::ND, float&gt; cType; </span></span>
<span class="line"><span>     typedef AscendC::MatmulType&lt;TPosition::GM, CubeFormat::ND, float&gt; biasType;</span></span>
<span class="line"><span>     MatMulKernel&lt;aType, bType, cType, biasType&gt;(...);</span></span>
<span class="line"><span>     ...</span></span>
<span class="line"><span> }</span></span></code></pre></div><p>【正例】</p><p>计算Matmul结果时，调用IterateAll接口或者GetTensorC接口搬运到矩阵D的GM地址上，同时将接口中enAtomic参数设为1，搬出到GM时，Matmul结果矩阵C会累加到矩阵D上，从而得到两个矩阵Add后的结果。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> template &lt;class A_TYPE, class B_TYPE, class C_TYPE, class BIAS_TYPE&gt;</span></span>
<span class="line"><span> __aicore__ inline void MatMulKernel(...)</span></span>
<span class="line"><span> {</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    AscendC::Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, CFG_MDL&gt; mm;</span></span>
<span class="line"><span>    TPipe pipe;</span></span>
<span class="line"><span>    REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    mm.SetTensorA(gm_a);</span></span>
<span class="line"><span>    mm.SetTensorB(gm_b);</span></span>
<span class="line"><span>    mm.SetBias(gm_bias);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    mm.IterateAll(gm_d, 1); // IterateAll接口中的enAtomic设为1</span></span>
<span class="line"><span>    // while (mm. Iterate()) {</span></span>
<span class="line"><span>        // mm.GetTensorC(gm_d, 1);</span><span>     // GetTensorC接口中的enAtomic设为1</span></span>
<span class="line"><span>    // }</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span> }</span></span>
<span class="line"><span></span></span>
<span class="line"><span> extern &quot;C&quot; __global__ __aicore__ void example_kernel(...)</span></span>
<span class="line"><span> {</span></span>
<span class="line"><span>     ...</span></span>
<span class="line"><span>     typedef AscendC::MatmulType&lt;TPosition::GM, CubeFormat::ND, half&gt; aType; </span></span>
<span class="line"><span>     typedef AscendC::MatmulType&lt;TPosition::GM, CubeFormat::ND, half&gt; bType; </span></span>
<span class="line"><span>     typedef AscendC::MatmulType&lt;TPosition::GM, CubeFormat::ND, float&gt; cType; </span></span>
<span class="line"><span>     typedef AscendC::MatmulType&lt;TPosition::GM, CubeFormat::ND, float&gt; biasType;</span></span>
<span class="line"><span>     MatMulKernel&lt;aType, bType, cType, biasType&gt;(...);</span></span>
<span class="line"><span>     ...</span></span>
<span class="line"><span> }</span></span></code></pre></div><p>【性能对比】</p><p><strong>图 1</strong> Matmul使能AtomicAdd选项前后性能对比<br><img src="`+l+'" alt="" title="Matmul使能AtomicAdd选项前后性能对比"></p><p>以矩阵维度M=64，N=256，K=256，矩阵D为(64, 256)为例，Matmul使能AtomicAdd选项前后的性能对比如上图所示，平均cycle数从开启AtomicAdd选项前的154181变为开启后的135054，性能优化12.4%。因此在这种场景下，使能AtomicAdd选项能获取更优的性能。</p>',12)])])}const A=s(t,[["render",i]]);export{T as __pageData,A as default};
